    current = read('/output/selection')
    if valid(current):
        result = current
    else:
        status('report')
else:
    if valid(result):
        write('/output/selection', result)
if exists('/output/selection') and valid(read('/output/selection')):
    delivery = status('report')
    if delivery == 'not_sent':
        send('report', 'team', read('/output/selection'))
    elif delivery == 'sent':
        pass
    else:
        receipt_state = receipt('report')
        if receipt_state == 'unattempted':
            send('report', 'team', read('/output/selection'))
